// Builds dist/ from src/: UMD files are copied as-is, ES module versions are
// generated by unwrapping the UMD factory. No dependencies.
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from 'node:fs';

const UMD_HEAD = /\(function \(root, factory\) \{[\s\S]*?\}\)\(typeof self !== 'undefined' \? self : this, function \(\) \{/;

function toESM(src, name, named) {
  if (!UMD_HEAD.test(src)) throw new Error(`${name}: UMD header not found`);
  const end = src.lastIndexOf('});');
  const body = src.slice(0, end).replace(UMD_HEAD, `const ${name} = (function () {`) + '})();\n';
  const exports = named.length ? `export const { ${named.join(', ')} } = ${name};\n` : '';
  return body + `export default ${name};\n` + exports;
}

mkdirSync('dist', { recursive: true });

const core = readFileSync('src/liquid-glass.js', 'utf8');
writeFileSync('dist/liquid-glass.js', core);
writeFileSync('dist/liquid-glass.mjs', toESM(core, 'LiquidGlass',
  ['attach', 'detach', 'get', 'init', 'initComponents', 'setLight', 'followPointer', 'textShape', 'attachText', 'PRESETS', 'DEFAULTS', 'supported']));

const gl = readFileSync('src/liquid-glass-gl.js', 'utf8');
writeFileSync('dist/liquid-glass-gl.js', gl);
writeFileSync('dist/liquid-glass-gl.mjs', toESM(gl, 'LiquidGlassGL', []));

copyFileSync('src/liquid-glass.css', 'dist/liquid-glass.css');
copyFileSync('src/liquid-glass.d.ts', 'dist/liquid-glass.d.ts');
copyFileSync('src/liquid-glass-gl.d.ts', 'dist/liquid-glass-gl.d.ts');

const kb = f => (readFileSync(f).length / 1024).toFixed(1) + ' KB';
for (const f of ['liquid-glass.js', 'liquid-glass.mjs', 'liquid-glass-gl.js', 'liquid-glass-gl.mjs', 'liquid-glass.css'])
  console.log(`dist/${f.padEnd(22)} ${kb('dist/' + f)}`);
